# The SERVER holds the data and answers requests
users = {"amira": "pass123", "ben": "qwerty", "chloe": "letmein"}
files = {"amira": ["essay.docx", "photo.png"], "ben": ["code.py"]}

def server(request, name, password=None):
    if request == "login":
        if users.get(name) == password:
            return "OK: welcome " + name
        return "DENIED: wrong username or password"
    if request == "files":
        return files.get(name, [])
    return "ERROR: unknown request"

# The CLIENT only sends requests and prints the reply
print(server("login", "amira", "pass123"))
print(server("login", "ben", "wrong"))
print(server("files", "amira"))
